import React, { useState } from 'react';
import { MultiSelect } from 'primereact/multiselect';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="multiSelect-accessibility">Accessible MultiSelect</label>
            <MultiSelect 
                id="multiSelect-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible MultiSelect input"
                placeholder="Enter multiSelect"
            />
        </div>
    );
}